  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// SQLite has no native enum support in Prisma, so these are plain strings.\n// Role: SUPER_ADMIN | LOAN_OFFICER | APPROVAL_MANAGER | ACCOUNTANT | MEMBER\n// MemberStatus: PENDING | ACTIVE | SUSPENDED | EXITED\n// SavingsType: REGULAR | TARGET | SHARES\n// InterestMethod: FLAT | REDUCING\n// LoanStatus: DRAFT | SUBMITTED | AWAITING_GUARANTORS | UNDER_REVIEW | RECOMMENDED |\n//   APPROVED | DISBURSED | ACTIVE | OVERDUE | COMPLETED | DEFAULTED | RESTRUCTURED | REJECTED\n// GuarantorStatus: PENDING | ACCEPTED | DECLINED\n// TxType: CONTRIBUTION | WITHDRAWAL | LOAN_DISBURSEMENT | LOAN_REPAYMENT | FEE | PENALTY | DIVIDEND | GUARANTOR_RECOVERY\n// TxDirection: CREDIT | DEBIT\n\nmodel User {\n  id           String    @id @default(cuid())\n  email        String    @unique\n  passwordHash String\n  role         String\n  status       String    @default(\"ACTIVE\")\n  lastLogin    DateTime?\n  createdAt    DateTime  @default(now())\n\n  member        Member?\n  auditLogs     AuditLog[]\n  notifications Notification[]\n  failedLogins  Int            @default(0)\n  lockedUntil   DateTime?\n\n  twoFactorSecret  String?\n  twoFactorEnabled Boolean @default(false)\n}\n\nmodel Member {\n  id                String   @id @default(cuid())\n  userId            String   @unique\n  user              User     @relation(fields: [userId], references: [id])\n  memberNo          String   @unique\n  firstName         String\n  lastName          String\n  phone             String?\n  address           String?\n  employer          String?\n  department        String?\n  nextOfKin         String?\n  bankName          String?\n  bankAccount       String?\n  passportUrl       String?\n  joinDate          DateTime @default(now())\n  status            String   @default(\"PENDING\")\n  membershipFeePaid Boolean  @default(false)\n  entranceFeePaid   Boolean  @default(false)\n  createdAt         DateTime @default(now())\n\n  documents       MemberDocument[]\n  savingsAccounts SavingsAccount[]\n  loans           Loan[]           @relation(\"MemberLoans\")\n  guarantorFor    LoanGuarantor[]\n  transactions    Transaction[]\n}\n\nmodel MemberDocument {\n  id        String   @id @default(cuid())\n  memberId  String\n  member    Member   @relation(fields: [memberId], references: [id])\n  type      String\n  fileUrl   String\n  createdAt DateTime @default(now())\n}\n\nmodel SavingsAccount {\n  id        String   @id @default(cuid())\n  memberId  String\n  member    Member   @relation(fields: [memberId], references: [id])\n  type      String   @default(\"REGULAR\")\n  balance   Int      @default(0)\n  createdAt DateTime @default(now())\n\n  transactions Transaction[]\n\n  @@unique([memberId, type])\n}\n\nmodel Transaction {\n  id         String          @id @default(cuid())\n  memberId   String\n  member     Member          @relation(fields: [memberId], references: [id])\n  accountId  String?\n  account    SavingsAccount? @relation(fields: [accountId], references: [id])\n  loanId     String?\n  loan       Loan?           @relation(fields: [loanId], references: [id])\n  type       String\n  amount     Int\n  direction  String\n  reference  String?\n  method     String?\n  recordedBy String?\n  createdAt  DateTime        @default(now())\n}\n\nmodel LoanProduct {\n  id                  String   @id @default(cuid())\n  name                String\n  rate                Float\n  method              String   @default(\"FLAT\")\n  minAmount           Int\n  maxAmount           Int\n  maxTenureMonths     Int\n  minMembershipMonths Int      @default(6)\n  savingsMultiplier   Float    @default(2)\n  guarantorsRequired  Int      @default(2)\n  processingFeePct    Float    @default(0)\n  penaltyRatePct      Float    @default(0)\n  active              Boolean  @default(true)\n  createdAt           DateTime @default(now())\n\n  loans Loan[]\n}\n\nmodel Loan {\n  id                 String      @id @default(cuid())\n  memberId           String\n  member             Member      @relation(\"MemberLoans\", fields: [memberId], references: [id])\n  productId          String\n  product            LoanProduct @relation(fields: [productId], references: [id])\n  amount             Int\n  tenureMonths       Int\n  rate               Float\n  method             String\n  purpose            String?\n  status             String      @default(\"DRAFT\")\n  processingFee      Int         @default(0)\n  totalInterest      Int         @default(0)\n  totalPayable       Int         @default(0)\n  monthlyPayment     Int         @default(0)\n  appliedAt          DateTime?\n  approvedBy         String?\n  disbursedAt        DateTime?\n  disbursedBy        String?\n  disbursementMethod String?\n  disbursementRef    String?\n  createdAt          DateTime    @default(now())\n\n  guarantors   LoanGuarantor[]\n  approvals    LoanApproval[]\n  schedule     RepaymentSchedule[]\n  repayments   Repayment[]\n  transactions Transaction[]\n}\n\nmodel LoanGuarantor {\n  id                String    @id @default(cuid())\n  loanId            String\n  loan              Loan      @relation(fields: [loanId], references: [id])\n  guarantorMemberId String\n  guarantor         Member    @relation(fields: [guarantorMemberId], references: [id])\n  amountGuaranteed  Int\n  status            String    @default(\"PENDING\")\n  respondedAt       DateTime?\n  createdAt         DateTime  @default(now())\n}\n\nmodel LoanApproval {\n  id        String   @id @default(cuid())\n  loanId    String\n  loan      Loan     @relation(fields: [loanId], references: [id])\n  stage     String\n  action    String\n  actorId   String\n  comment   String?\n  createdAt DateTime @default(now())\n}\n\nmodel RepaymentSchedule {\n  id           String   @id @default(cuid())\n  loanId       String\n  loan         Loan     @relation(fields: [loanId], references: [id])\n  instalmentNo Int\n  dueDate      DateTime\n  principal    Int\n  interest     Int\n  amountDue    Int\n  amountPaid   Int      @default(0)\n  status       String   @default(\"PENDING\")\n}\n\nmodel Repayment {\n  id         String   @id @default(cuid())\n  loanId     String\n  loan       Loan     @relation(fields: [loanId], references: [id])\n  amount     Int\n  paidAt     DateTime @default(now())\n  method     String?\n  reference  String?\n  recordedBy String?\n}\n\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  title     String\n  body      String\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  actorId   String?\n  actor     User?    @relation(fields: [actorId], references: [id])\n  action    String\n  entity    String\n  entityId  String?\n  oldValue  String?\n  newValue  String?\n  createdAt DateTime @default(now())\n}\n\nmodel Settings {\n  key   String @id\n  value String\n}\n",
